'use client';
import { useState, useEffect } from 'react';
import { FileUpload } from '@/components/FileUpload';
import { PasteInput } from '@/components/PasteInput';
import { ProgressBar } from '@/components/ProgressBar';
import { Button } from '@/components/ui/button';
import { Download, AlertTriangle, CheckCircle, XCircle, Loader2, FileText, Type } from 'lucide-react';
import axios from 'axios';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { motion, AnimatePresence } from 'framer-motion';

interface ValidationStats {
    total: number;
    processed: number;
    valid: number;
    invalid: number;
    risky: number;
}

export default function Dashboard() {
    // Tabs: 'upload' | 'paste'
    const [activeTab, setActiveTab] = useState<'upload' | 'paste'>('upload');

    const [jobId, setJobId] = useState<string | null>(null);
    const [status, setStatus] = useState<string>('idle'); // idle, active, completed, failed
    const [stats, setStats] = useState<ValidationStats>({ total: 0, processed: 0, valid: 0, invalid: 0, risky: 0 });
    const [results, setResults] = useState<any[]>([]);

    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (jobId && status !== 'completed' && status !== 'failed') {
            interval = setInterval(async () => {
                try {
                    const res = await axios.get(`http://localhost:3001/api/status/${jobId}`);
                    const data = res.data;
                    const newStatus = data.state;

                    if (newStatus !== status) {
                        if (newStatus === 'completed') toast.success("Validation completed!");
                        if (newStatus === 'failed') toast.error("Validation failed.");
                        setStatus(newStatus);
                    }

                    if (data.result) {
                        const resList = data.result;
                        const valid = resList.filter((r: any) => r.status === 'valid').length;
                        const invalid = resList.filter((r: any) => r.status === 'invalid').length;
                        const risky = resList.filter((r: any) => r.status === 'risky').length;
                        setStats({
                            total: resList.length,
                            processed: resList.length,
                            valid,
                            invalid,
                            risky
                        });
                        setResults(resList);
                    } else {
                        setStats(prev => ({ ...prev, processed: Math.floor((data.progress / 100) * prev.total) }));
                    }

                } catch (err) {
                    console.error(err);
                }
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [jobId, status]);

    const handleStart = (id: string, total: number) => {
        setJobId(id);
        setStats({ total, processed: 0, valid: 0, invalid: 0, risky: 0 });
        setStatus('active');
        toast.info("Started validation job...");
    };

    const handleError = (msg: string) => {
        toast.error(msg);
    };

    const downloadReport = (type: 'valid' | 'invalid' | 'full') => {
        if (!results.length) return;
        let dataToExport = results;
        if (type === 'valid') dataToExport = results.filter(r => r.status === 'valid');
        if (type === 'invalid') dataToExport = results.filter(r => r.status === 'invalid');

        const csvContent = "data:text/csv;charset=utf-8,"
            + "Email,Status,Reason\n"
            + dataToExport.map(e => `${e.email},${e.status},${e.reason || ''}`).join("\n");

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `email_report_${type}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        toast.success(`Downloaded ${type} report.`);
    };

    const progress = stats.total > 0 ? Math.round((stats.processed / stats.total) * 100) : 0;

    return (
        <div className="max-w-4xl mx-auto space-y-8">
            {status === 'idle' && (
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                    <div className="flex border-b border-slate-200">
                        <button
                            onClick={() => setActiveTab('upload')}
                            className={cn("flex-1 py-4 text-sm font-medium flex items-center justify-center gap-2 transition-colors", activeTab === 'upload' ? "bg-white text-indigo-600 border-b-2 border-indigo-600" : "bg-slate-50 text-slate-500 hover:bg-slate-100")}
                        >
                            <FileText className="w-4 h-4" /> Upload File
                        </button>
                        <button
                            onClick={() => setActiveTab('paste')}
                            className={cn("flex-1 py-4 text-sm font-medium flex items-center justify-center gap-2 transition-colors", activeTab === 'paste' ? "bg-white text-indigo-600 border-b-2 border-indigo-600" : "bg-slate-50 text-slate-500 hover:bg-slate-100")}
                        >
                            <Type className="w-4 h-4" /> Paste Emails
                        </button>
                    </div>

                    <div className="p-8 min-h-[300px] flex flex-col justify-center">
                        <h2 className="text-xl font-semibold mb-2 text-center text-slate-700">
                            {activeTab === 'upload' ? 'Upload or Drag & Drop' : 'Paste Your List'}
                        </h2>
                        <p className="text-slate-400 text-center text-sm mb-8">
                            {activeTab === 'upload' ? 'Supports CSV and Excel files.' : 'Copy and paste emails directly.'}
                        </p>

                        <AnimatePresence mode='wait'>
                            {activeTab === 'upload' ? (
                                <motion.div key="upload" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}>
                                    <FileUpload onUploadStart={handleStart} onError={handleError} />
                                </motion.div>
                            ) : (
                                <motion.div key="paste" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}>
                                    <PasteInput onUploadStart={handleStart} onError={handleError} />
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>
                </div>
            )}

            {(status === 'active' || status === 'completed' || status === 'delayed') && (
                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} className="space-y-6">
                    <div className="bg-white rounded-2xl shadow-lg p-8 border border-slate-100 relative overflow-hidden">
                        {/* Background decoration */}
                        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-50 rounded-bl-full -mr-32 -mt-32 opacity-50 pointer-events-none" />

                        <div className="relative">
                            <div className="flex justify-between items-center mb-6">
                                <div>
                                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                        {status === 'completed' ? <CheckCircle className="text-green-500" /> : <Loader2 className="animate-spin text-indigo-500" />}
                                        {status === 'completed' ? 'Analysis Complete' : 'Processing Emails...'}
                                    </h2>
                                    <p className="text-slate-400 text-sm">Job ID: {jobId}</p>
                                </div>
                                <div className="text-3xl font-black text-slate-200">{progress}%</div>
                            </div>

                            <ProgressBar progress={progress} />

                            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-8">
                                <StatCard label="Total" value={stats.total} color="bg-slate-50 text-slate-600" />
                                <StatCard label="Valid" value={stats.valid} color="bg-green-50 text-green-700" icon={<CheckCircle className="w-4 h-4" />} />
                                <StatCard label="Invalid" value={stats.invalid} color="bg-red-50 text-red-700" icon={<XCircle className="w-4 h-4" />} />
                                <StatCard label="Risky" value={stats.risky} color="bg-yellow-50 text-yellow-700" icon={<AlertTriangle className="w-4 h-4" />} />
                            </div>
                        </div>
                    </div>

                    {status === 'completed' && (
                        <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>
                            <div className="bg-slate-900 text-white rounded-2xl shadow-xl p-8 flex flex-col md:flex-row items-center justify-between gap-6 border border-slate-700/50">
                                <div>
                                    <h3 className="text-xl font-bold mb-1">Download Report</h3>
                                    <p className="text-slate-400 text-sm">Export your cleaned list in CSV format.</p>
                                </div>
                                <div className="flex gap-3">
                                    <Button onClick={() => downloadReport('valid')} className="bg-green-600 hover:bg-green-700 text-white h-11 px-6">
                                        <Download className="w-4 h-4 mr-2" /> Valid Only
                                    </Button>
                                    <Button onClick={() => downloadReport('full')} variant="secondary" className="h-11 px-6">
                                        Full Report
                                    </Button>
                                </div>
                                <Button variant="ghost" className="text-slate-400 hover:text-white" onClick={() => { setStatus('idle'); setResults([]); setJobId(null); }}>
                                    Start New Validation
                                </Button>
                            </div>
                        </motion.div>
                    )}
                </motion.div>
            )}
        </div>
    );
}

function StatCard({ label, value, color, icon }: any) {
    return (
        <div className={cn("p-4 rounded-xl flex flex-col items-center justify-center text-center transition-all hover:scale-105 cursor-default", color)}>
            <div className="text-xs font-semibold uppercase tracking-wider opacity-70 mb-2 flex items-center gap-1">
                {icon} {label}
            </div>
            <div className="text-3xl font-bold">{value}</div>
        </div>
    )
}
